-- Dhaba Desk schema, PHP 8.2+, MySQL 8 / MariaDB 10.6+.
CREATE TABLE IF NOT EXISTS dd_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL,session_rev INT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_settings (`key` VARCHAR(100) PRIMARY KEY,value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_login_attempts (id CHAR(64) PRIMARY KEY,attempts INT NOT NULL DEFAULT 0,expires BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_employees (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,job VARCHAR(100),salary BIGINT NOT NULL DEFAULT 0,pay_basis VARCHAR(20) NOT NULL DEFAULT 'monthly',active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_days (date DATE PRIMARY KEY,opening BIGINT NOT NULL DEFAULT 0,opening_set TINYINT NOT NULL DEFAULT 0,counted BIGINT NULL,status VARCHAR(20) NOT NULL DEFAULT 'open',note TEXT NULL,closed_by BIGINT UNSIGNED NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_ledger (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,date DATE NOT NULL,name VARCHAR(160) NOT NULL,type VARCHAR(30) NOT NULL,account VARCHAR(40) NOT NULL,to_account VARCHAR(40) NULL,amount BIGINT NOT NULL,category VARCHAR(80),reference VARCHAR(120),description TEXT,employee_id BIGINT UNSIGNED NULL,payroll_month CHAR(7) NULL,source VARCHAR(40) NOT NULL DEFAULT 'manual',source_key VARCHAR(191) NULL UNIQUE,voided TINYINT NOT NULL DEFAULT 0,created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_day(date,voided),INDEX idx_payroll(employee_id,payroll_month,type),CONSTRAINT dd_ledger_employee FOREIGN KEY(employee_id) REFERENCES dd_employees(id),CHECK(amount>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_attendance (employee_id BIGINT UNSIGNED NOT NULL,date DATE NOT NULL,status VARCHAR(30) NOT NULL,PRIMARY KEY(employee_id,date),FOREIGN KEY(employee_id) REFERENCES dd_employees(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_payroll (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,employee_id BIGINT UNSIGNED NOT NULL,month CHAR(7) NOT NULL,base BIGINT NOT NULL,overtime BIGINT NOT NULL,bonus BIGINT NOT NULL,deductions BIGINT NOT NULL,advance BIGINT NOT NULL,gross BIGINT NOT NULL,net BIGINT NOT NULL,approved TINYINT NOT NULL DEFAULT 0,UNIQUE(employee_id,month),FOREIGN KEY(employee_id) REFERENCES dd_employees(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_inventory (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,unit VARCHAR(40) NOT NULL,quantity DECIMAL(14,3) NOT NULL DEFAULT 0,reorder DECIMAL(14,3) NOT NULL DEFAULT 0,cost BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_stock_moves (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,item_id BIGINT UNSIGNED NOT NULL,date DATE NOT NULL,quantity DECIMAL(14,3) NOT NULL,reason TEXT,FOREIGN KEY(item_id) REFERENCES dd_inventory(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_suppliers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,phone VARCHAR(40),notes TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_bills (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,supplier_id BIGINT UNSIGNED NOT NULL,reference VARCHAR(120) NOT NULL,date DATE NOT NULL,due_date DATE NOT NULL,amount BIGINT NOT NULL,ledger_id BIGINT UNSIGNED NULL,UNIQUE(supplier_id,reference),FOREIGN KEY(supplier_id) REFERENCES dd_suppliers(id),FOREIGN KEY(ledger_id) REFERENCES dd_ledger(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_reservations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,date DATE NOT NULL,time CHAR(5) NOT NULL,name VARCHAR(160) NOT NULL,phone VARCHAR(40),covers INT NOT NULL,status VARCHAR(30),notes TEXT,INDEX(date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_feedback (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,date DATE NOT NULL,rating TINYINT NOT NULL,comment TEXT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'new',response TEXT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_paytm (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,external_id VARCHAR(120) NOT NULL UNIQUE,date DATE NOT NULL,reference VARCHAR(120),amount BIGINT NOT NULL,status VARCHAR(30) NOT NULL,kind VARCHAR(30) NOT NULL,fee BIGINT NOT NULL DEFAULT 0,ledger_id BIGINT UNSIGNED NULL,matched_id BIGINT UNSIGNED NULL UNIQUE,FOREIGN KEY(ledger_id) REFERENCES dd_ledger(id),FOREIGN KEY(matched_id) REFERENCES dd_ledger(id),INDEX(date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,detail MEDIUMTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_menu (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,category VARCHAR(80),price BIGINT NOT NULL,active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,date DATE NOT NULL,kind VARCHAR(30),table_no VARCHAR(20),items MEDIUMTEXT NOT NULL,subtotal BIGINT NOT NULL,discount BIGINT NOT NULL,tax BIGINT NOT NULL,total BIGINT NOT NULL,reference VARCHAR(120) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dd_staff_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kind VARCHAR(30) NOT NULL,date DATE NOT NULL,payload MEDIUMTEXT NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(kind,date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
